INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('576dc901-367c-491c-88a5-7633757d1521', 'c3c3c3c3-3030-4000-8000-000000000003', 14, 'Dia 14 — Silêncio', 'Semana 2: Organizar', '{"pch": "Aquietai-vos\u2026 No sil\u00eancio, os pensamentos se acomodam como sedimento na \u00e1gua.", "verse": "Sl 46,10", "lectio": "Leia Sl 46. Deus \u00e9 ref\u00fagio.", "practice": "15 minutos de sil\u00eancio contemplativo. Sem guia, sem m\u00fasica.", "question": "O que aparece quando tudo fica em sil\u00eancio?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;